REAL_NOW = datetime.now(timezone.utc)
_clock = {"t": REAL_NOW}


def fake_now():
    return _clock["t"]


@contextmanager
def at(days_ago: float, hour: int = 11):
    """Run service calls as if it were `days_ago` days in the past."""
    t = (REAL_NOW - timedelta(days=days_ago)).replace(hour=hour, minute=random.randint(0, 50), second=0,
                                                      microsecond=0)
    prev = _clock["t"]
    _clock["t"] = min(t, REAL_NOW)
    try:
        yield _clock["t"]
    finally:
        _clock["t"] = prev


def tick(minutes: int):
    _clock["t"] = _clock["t"] + timedelta(minutes=minutes)


for mod in (common, crm, sales, stock, field, support, finance, reports, serializers):
    mod.now = fake_now


@event.listens_for(Base, "before_insert", propagate=True)
def _stamp(mapper, connection, target):
    for attr in ("created_at", "paid_at"):
        if hasattr(target, attr) and getattr(target, attr) is None:
            setattr(target, attr, _clock["t"])


