def kit_spec(kind: str, kw: int):
    panels = {1: 2, 2: 4, 3: 6, 5: 10}[kw]
    if kind == "panel_set":
        return [("PNL-WAA-540D", panels), ("STR-GI-1KW", kw), ("CBL-DC-4", max(1, kw // 2))]
    common_lines = [("PNL-WAA-540D", panels), ("STR-GI-1KW", kw), ("CBL-DC-4", max(1, kw // 2 + 1)),
                    ("CBL-AC-6", 1), ("ACDB-1P", 1), ("DCDB-2S", 1), ("EARTH-KIT", 1), ("LA-ESE", 1),
                    ("SRV-INST", kw)]
    if kind == "on_grid":
        return common_lines + [("INV-GRW-5K" if kw >= 4 else "INV-GRW-3K", 1)]
    batteries = {1: 2, 2: 4, 3: 4, 5: 8}[kw]
    return common_lines + [("INV-LUM-3K", 1), ("BAT-EXI-150", batteries), ("CC-UTL-50A", 1)]


