def make_photo(kind: str) -> bytes:
    img = Image.new("RGB", (960, 640), (226, 232, 240))
    d = ImageDraw.Draw(img)
    if kind == "roof":
        d.rectangle([0, 380, 960, 640], fill=(148, 113, 89))
        for r in range(2):
            for c in range(5):
                x, y = 120 + c * 150, 140 + r * 120
                d.rectangle([x, y, x + 140, y + 110], fill=(30, 58, 138), outline=(203, 213, 225), width=4)
                for k in range(1, 4):
                    d.line([x + k * 35, y, x + k * 35, y + 110], fill=(59, 130, 246), width=1)
    elif kind == "inverter_serial":
        d.rectangle([330, 120, 630, 520], fill=(241, 245, 249), outline=(71, 85, 105), width=6)
        d.rectangle([370, 170, 590, 250], fill=(15, 23, 42))
        d.text((385, 300), "S/N: GRW3K-XXXX", fill=(15, 23, 42))
    else:
        d.rectangle([200, 160, 760, 480], fill=(254, 243, 199), outline=(180, 83, 9), width=5)
    buf = io.BytesIO()
    img.save(buf, "JPEG", quality=80)
    return buf.getvalue()


def signature_data_url() -> str:
    img = Image.new("RGBA", (480, 160), (255, 255, 255, 0))
    d = ImageDraw.Draw(img)
    pts = [(30 + i * 14, 90 + int(30 * ((-1) ** i) * random.random())) for i in range(30)]
    d.line(pts, fill=(15, 23, 42, 255), width=4, joint="curve")
    buf = io.BytesIO()
    img.save(buf, "PNG")
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode()


