def reset():
    Base.metadata.drop_all(engine)
    with engine.begin() as conn:
        for seq in ("order_number_seq", "invoice_number_seq", "ticket_number_seq", "purchase_number_seq"):
            conn.execute(text(f"DROP SEQUENCE IF EXISTS {seq}"))
    Base.metadata.create_all(engine)


def run():
    db = SessionLocal()
    u = {}
    for name, email, role, rate in USERS:
        user = User(name=name, email=email, role=role, password_hash=hash_password(PASSWORD),
                    hourly_rate=Decimal(rate), phone=f"98{random.randint(10000000, 99999999)}")
        db.add(user)
        u[email.split("@")[0]] = user
    db.commit()
    admin, priya, arjun = u["director"], u["priya"], u["arjun"]
    techs = [u["ravi"], u["suresh"], u["imran"], u["kiran"]]
    wh, sup, acc = u["warehouse"], u["support"], u["accounts"]

    prods = {}
    for sku, name, cat, brand, model, watt, unit, cost, sale, wm, ser, dcr, reorder in PRODUCTS:
        p = Product(sku=sku, name=name, category=cat, brand=brand, model=model, wattage=watt, unit=unit,
                    cost_price=Decimal(cost), sale_price=Decimal(sale), warranty_months=wm, is_serialized=ser,
                    is_dcr=dcr, reorder_level=reorder)
        db.add(p)
        prods[sku] = p
    db.commit()

    names = {"panel_set": "Panel Set", "on_grid": "On-Grid", "off_grid": "Off-Grid"}
    kits = {}
    for kind in ("panel_set", "on_grid", "off_grid"):
        for kw in (1, 2, 3, 5):
            k = KitTemplate(name=f"{names[kind]} {kw} kW", capacity_kw=Decimal(kw), system_type=kind,
                            includes_installation=kind != "panel_set")
            for sku, qty in kit_spec(kind, kw):
                k.lines.append(KitLine(product_id=prods[sku].id, qty=qty))
            db.add(k)
            kits[(kind, kw)] = k
    db.commit()

    sups = [Supplier(name="Waaree Energies Ltd (Distributor)", phone="9820011111", gstin="27AAACW1234F1Z5"),
            Supplier(name="Growatt India Pvt Ltd", phone="9810022222", gstin="06AAGCG5678K1Z2"),
            Supplier(name="Deccan Electricals & Solar", phone="9848033333", gstin="36AABCD9012M1Z9")]
    db.add_all(sups)
    db.commit()

    # ----- purchases (stock coming in, with serials) -----
    def buy(days_ago, supplier, items):
        with at(days_ago, 10):
            po = stock.create_purchase(db, PurchaseIn(supplier_id=supplier.id, lines=[
                PurchaseLineIn(product_id=prods[s].id, qty=q, unit_cost=float(prods[s].cost_price))
                for s, q, _ in items]), wh)
            stock.mark_ordered(db, po.id, wh)
        with at(days_ago - 3, 15):
            recv = []
            for ln, (sku, qty, prefix) in zip(po.lines, items):
                serials = [f"{prefix}{days_ago:03d}{i:04d}" for i in range(1, qty + 1)] if prods[sku].is_serialized else []
                recv.append(ReceiveLineIn(line_id=ln.id, serials=serials))
            stock.receive_purchase(db, po.id, ReceiveIn(lines=recv), wh)

    buy(98, sups[0], [("PNL-WAA-540D", 70, "WAA540-"), ("PNL-ADA-545D", 20, "ADA545-"), ("PNL-IMP-550", 12, "SMX550-"),
                      ("STR-GI-1KW", 40, ""), ("CBL-DC-4", 40, "")])
    buy(95, sups[1], [("INV-GRW-3K", 12, "GRW3K-"), ("INV-GRW-5K", 6, "GRW5K-"), ("INV-LUM-3K", 4, "LUM3K-")])
    buy(94, sups[2], [("BAT-EXI-150", 16, "EXI150-"), ("CC-UTL-50A", 5, "UTL50-"), ("CBL-AC-6", 30, ""),
                      ("ACDB-1P", 20, ""), ("DCDB-2S", 20, ""), ("EARTH-KIT", 20, ""), ("LA-ESE", 20, "")])
    buy(40, sups[0], [("PNL-WAA-540D", 50, "WAA540-"), ("STR-GI-1KW", 20, "")])
    # a draft purchase waiting to be ordered
    with at(2, 12):
        stock.create_purchase(db, PurchaseIn(supplier_id=sups[1].id, lines=[
            PurchaseLineIn(product_id=prods["INV-GRW-3K"].id, qty=6, unit_cost=29500),
            PurchaseLineIn(product_id=prods["INV-GRW-5K"].id, qty=3, unit_cost=41000)]), wh)

    # ----- customers and leads -----
    leads = []
    # how many days ago each enquiry arrived (older = further along the pipeline)
    lead_days = [92, 88, 84, 80, 76, 70, 72, 66, 62, 58, 44, 34, 28, 22, 14, 4, 11, 8, 12, 6, 5, 3, 2.5, 1.2, 0.4]
    for i, (name, phone, city, addr, pin, kw, kind, subsidy, source, bill) in enumerate(CUSTOMERS):
        days = lead_days[i]
        with at(days, 9 + i % 8):
            lead, _ = crm.create_lead(db, LeadIn(name=name, phone=phone, city=city, address=addr, pincode=pin,
                                                 requested_kw=kw, system_type=kind, wants_subsidy=subsidy,
                                                 source=source, monthly_bill=bill,
                                                 assigned_to=(priya if i % 2 == 0 else arjun).id), priya)
            leads.append((lead, days))

    def qualify(lead, days, mismatch=False):
        c = lead.customer
        with at(days - 0.5, 12):
            crm.transition_lead(db, lead.id, LeadTransitionIn(to="contacted"), priya)
            crm.update_lead(db, lead.id, LeadUpdate(
                roof_area_sqft=float(lead.requested_kw) * 110 + random.randint(20, 120), shadow_free=True,
                grid_suitable=True, consumer_no=f"{random.randint(100000000, 999999999)}",
                aadhaar_name=c.name, bill_name=c.name if not mismatch else c.name.split()[0] + " " + "K. " + c.name.split()[-1],
                bank_account_name=c.name.upper(), bank_aadhaar_seeded=not mismatch), priya)
            crm.transition_lead(db, lead.id, LeadTransitionIn(to="qualified"), priya)

    def survey(lead, days, tech, approve=True, submit=True):
        with at(days - 1, 10):
            s = crm.schedule_survey(db, lead.id, SurveyCreate(technician_id=tech.id, scheduled_at=fake_now() + timedelta(days=1)), priya)
        if not submit:
            return s
        with at(days - 2, 16):
            crm.submit_survey(db, s.id, SurveySubmit(roof_direction=random.choice(["S", "SE", "SW"]),
                                                     tilt_deg=random.choice([12, 15, 18, 20]),
                                                     cable_distance_m=random.randint(8, 30),
                                                     usable_area_sqft=float(lead.requested_kw) * 100 + 60,
                                                     notes="Clear south-facing roof, no shading after 9 AM."), tech)
        if approve:
            with at(days - 2.5, 11):
                crm.review_survey(db, s.id, True, priya)
        return s

    def quote(lead, days, discount=None, swap_non_dcr=False):
        kind, kw = lead.system_type, int(lead.requested_kw)
        with at(days - 3, 12):
            o = sales.create_quote(db, lead.id, QuoteIn(kit_id=kits[(kind, kw)].id, is_subsidy=lead.wants_subsidy), priya)
            if discount:
                sales.update_order(db, o.id, OrderUpdate(lines=[
                    OrderLineIn(product_id=ln.product_id, qty=ln.qty, unit_price=float(ln.unit_price) * (1 - discount))
                    for ln in o.lines]), priya)
            sales.send_quote(db, o.id, priya)
        return o

    def confirm(o, days, full=False):
        with at(days - 4, 15):
            o = sales.get_order(db, o.id)
            amount = float(o.total) if full else round(float(o.total) * random.choice([0.4, 0.5]), -2)
            return sales.confirm_order(db, o.id, ConfirmIn(advance_amount=amount, method=random.choice(["upi", "bank_transfer"]),
                                                           reference=f"UTR{random.randint(10**9, 10**10)}"), priya,
                                       f"seed-confirm-{o.id}")

    def dispatch_order(o, days, scan_all=True):
        pl = db.execute(select(PickList).where(PickList.order_id == o.id)).scalar_one()
        units = db.execute(select(StockUnit).where(StockUnit.order_id == o.id)).scalars().all()
        with at(days - 6, 10):
            for k, unit in enumerate(units):
                if not scan_all and k >= len(units) // 2:
                    break
                stock.scan_serial(db, pl.id, unit.serial_no, wh)
            if scan_all:
                stock.dispatch(db, pl.id, wh)

    def deliver_order(o, days):
        with at(days - 7, 13):
            stock.deliver(db, o.id, wh)

    def feasibility(o, days):
        case = field.subsidy_case_for_order(db, o.id)
        with at(days - 6.5, 12):
            field.advance_case(db, case.id, SubsidyAdvanceIn(to_stage="feasibility_approved",
                                                             application_no=f"PMSG-{o.customer.city[:3].upper()}-{random.randint(100000, 999999)}"), priya)
        return case

    def install(o, days, tech, gps_ok=True, finish=True):
        job = db.execute(select(Job).where(Job.order_id == o.id)).scalar_one()
        with at(days - 8, 9):
            start = fake_now() + timedelta(hours=1)
            field.schedule_job(db, job.id, ScheduleIn(technician_id=tech.id, scheduled_start=start,
                                                      scheduled_end=start + timedelta(hours=6)), priya)
        if not finish:
            return job
        with at(days - 8, 10):
            field.start_job(db, job.id, tech)
            tick(60)
            serials = [s.serial_no for s in db.execute(select(StockUnit).where(StockUnit.order_id == o.id)).scalars()]
            field.link_serials(db, job.id, serials, tech)
            lat, lng = CITY_GPS[o.customer.city]
            for kind in ("roof", "inverter_serial", "wiring"):
                tick(40)
                has_gps = gps_ok or kind != "inverter_serial"
                field.add_photo(db, "job", job.id, kind, make_photo(kind), "image/jpeg",
                                lat + random.uniform(-0.03, 0.03) if has_gps else None,
                                lng + random.uniform(-0.03, 0.03) if has_gps else None, fake_now())
            tick(random.randint(180, 260))
            field.complete_job(db, job.id, JobCompleteIn(installed_kw=float(o.capacity_kw),
                                                         signed_by_name=o.customer.name,
                                                         signature_data_url=signature_data_url(),
                                                         notes="System tested. Generation verified on inverter display."), tech)
        return job

    def subsidy_through(o, days, upto):
        case = field.subsidy_case_for_order(db, o.id)
        steps = [("inspection_submitted", 10), ("net_meter_installed", 32), ("subsidy_credited", 50)]
        for stage, offset in steps:
            if days - offset < 0:
                break
            with at(days - offset, 12):
                if stage == "inspection_submitted":
                    field.submit_inspection(db, case.id, priya)
                else:
                    field.advance_case(db, case.id, SubsidyAdvanceIn(to_stage=stage), priya)
            if stage == upto:
                break

    def pay_balance(o, days, part=1.0):
        inv = db.execute(select(Invoice).where(Invoice.order_id == o.id)).scalar_one()
        bal = float(inv.total - inv.amount_paid)
        if bal <= 0:
            return
        with at(max(days - 12, 0.2), 14):
            finance.record_payment(db, inv.id, PaymentIn(amount=round(bal * part, 2), method="bank_transfer",
                                                         reference=f"NEFT{random.randint(10**8, 10**9)}"), acc,
                                   f"seed-pay-{inv.id}-{part}")

    L = [lead for lead, _ in leads]
    D = [d for _, d in leads]

    # Completed, fully through subsidy (oldest)
    full_flow = [(0, "subsidy_credited", 1.0, 0), (1, "subsidy_credited", 1.0, 1), (2, "net_meter_installed", 1.0, 2),
                 (3, "net_meter_installed", 0.5, 3), (4, "inspection_submitted", 1.0, 0), (7, "inspection_submitted", 0.0, 1),
                 (8, "inspection_submitted", 0.6, 2)]
    completed_orders = {}
    for idx, upto, pay, t in full_flow:
        lead, days = L[idx], D[idx]
        qualify(lead, days)
        survey(lead, days, techs[t])
        o = quote(lead, days, discount=0.36 if idx == 8 else None)  # idx 8: heavy discount -> loss-making job
        o = confirm(o, days)
        dispatch_order(o, days)
        deliver_order(o, days)
        if o.is_subsidy:
            feasibility(o, days)
        install(o, days, techs[t])
        if o.is_subsidy and upto:
            subsidy_through(o, days, upto)
        if pay:
            pay_balance(o, days, pay)
        completed_orders[idx] = o

    # Off-grid, no subsidy, completed (idx 6) and panel-only set (idx 9)
    for idx, t in ((6, 3), (9, 0)):
        lead, days = L[idx], D[idx]
        qualify(lead, days)
        survey(lead, days, techs[t])
        o = quote(lead, days)
        o = confirm(o, days, full=idx == 9)
        dispatch_order(o, days)
        deliver_order(o, days)
        if o.includes_installation:
            install(o, days, techs[t])
        completed_orders[idx] = o

    # Installed, subsidy gate FAILS (photo without GPS) -> demo the inspection checklist (idx 10)
    lead, days = L[10], D[10]
    qualify(lead, days)
    survey(lead, days, techs[1])
    o = confirm(quote(lead, days), days)
    dispatch_order(o, days); deliver_order(o, days); feasibility(o, days)
    install(o, days, techs[1], gps_ok=False)
    completed_orders[10] = o

    # Delivered + feasibility approved + job scheduled for today -> demo mobile install form (idx 11)
    lead, days = L[11], D[11]
    qualify(lead, days)
    survey(lead, days, techs[0])
    o = confirm(quote(lead, days), days)
    dispatch_order(o, days); deliver_order(o, days); feasibility(o, days)
    job = db.execute(select(Job).where(Job.order_id == o.id)).scalar_one()
    with at(0.3, 8):
        start = REAL_NOW.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)
        field.schedule_job(db, job.id, ScheduleIn(technician_id=techs[0].id, scheduled_start=start,
                                                  scheduled_end=start + timedelta(hours=6)), priya)

    # Delivered but DISCOM feasibility still pending -> demo FEASIBILITY_NOT_APPROVED (idx 12)
    lead, days = L[12], D[12]
    qualify(lead, days)
    survey(lead, days, techs[2])
    o = confirm(quote(lead, days), days)
    dispatch_order(o, days); deliver_order(o, days)
    job = db.execute(select(Job).where(Job.order_id == o.id)).scalar_one()
    with at(1, 9):
        start = REAL_NOW.replace(minute=0, second=0, microsecond=0) + timedelta(days=1, hours=2)
        field.schedule_job(db, job.id, ScheduleIn(technician_id=techs[2].id, scheduled_start=start,
                                                  scheduled_end=start + timedelta(hours=6)), priya)
    with at(0.5, 10):
        case = field.subsidy_case_for_order(db, o.id)
        case.application_no = f"PMSG-JAI-{random.randint(100000, 999999)}"
        db.commit()

    # Dispatched, awaiting delivery (idx 13)
    lead, days = L[13], D[13]
    qualify(lead, days); survey(lead, days, techs[3])
    o = confirm(quote(lead, days), days)
    dispatch_order(o, days)

    # Confirmed, half scanned in the warehouse -> demo the dispatch scanner (idx 16)
    lead, days = L[16], D[16]
    qualify(lead, days); survey(lead, days, techs[1])
    o = confirm(quote(lead, days), days)
    dispatch_order(o, days, scan_all=False)

    # Confirmed, nothing scanned yet (idx 17)
    lead, days = L[17], D[17]
    qualify(lead, days); survey(lead, days, techs[2])
    confirm(quote(lead, days), days)

    # Quotes sent, not yet confirmed (idx 14 non-subsidy, idx 18 off-grid)
    for idx in (14, 18):
        lead, days = L[idx], D[idx]
        qualify(lead, days); survey(lead, days, techs[idx % 4])
        quote(lead, days)

    # Survey approved, ready to quote -> demo quote builder (idx 19, with NAME MISMATCH for R-CRM-3)
    lead, days = L[19], D[19]
    qualify(lead, days, mismatch=True); survey(lead, days, techs[3])

    # Survey submitted, waiting for approval (idx 20)
    lead, days = L[20], D[20]
    qualify(lead, days); survey(lead, days, techs[0], approve=False)

    # Survey scheduled -> demo "can't quote before survey" (idx 15)
    lead, days = L[15], D[15]
    qualify(lead, days); survey(lead, days, techs[1], submit=False)

    # Qualified (idx 21), contacted (idx 22), new (23, 24), lost (5)
    qualify(L[21], D[21])
    with at(D[22] - 0.5, 12):
        crm.transition_lead(db, L[22].id, LeadTransitionIn(to="contacted"), arjun)
    with at(D[5] - 1, 15):
        crm.transition_lead(db, L[5].id, LeadTransitionIn(to="contacted"), priya)
        crm.transition_lead(db, L[5].id, LeadTransitionIn(to="lost", lost_reason="Chose a competitor's cheaper quote"), priya)
    for idx in (22, 23, 24):
        with at(max(D[idx] - 1, 0.2), 16):
            crm.add_note(db, L[idx].id, "Customer asked about EMI options and PM Surya Ghar subsidy timelines.", arjun)

    # ----- legacy customer with an expired inverter warranty (installed 2.5 years ago) -----
    with at(5, 10):
        legacy = Customer(name="Prakash Jain", phone="9829267890", city="Jaipur", address="Bapu Nagar",
                          pincode="302015", aadhaar_name="Prakash Jain", bill_name="Prakash Jain",
                          bank_account_name="PRAKASH JAIN", bank_aadhaar_seeded=True, monthly_bill=Decimal(2800))
        db.add(legacy)
        db.flush()
        old_install = REAL_NOW - timedelta(days=900)
        old_inv = StockUnit(product_id=prods["INV-GRW-3K"].id, serial_no="GRW3K-2024LEG0007", unit_cost=Decimal(27500),
                            status="installed", customer_id=legacy.id, delivered_at=old_install,
                            warranty_end=common.add_months(old_install.date(), 24), qr_token="legacy-demo-unit-0007")
        db.add(old_inv)
        db.commit()

    # ----- service tickets -----
    def unit_of(o, category):
        return db.execute(select(StockUnit).join(Product).where(StockUnit.order_id == o.id,
                                                                Product.category == category)).scalars().first()

    lat, lng = CITY_GPS["Hyderabad"]
    # 1) In-warranty inverter failure, replaced, resolved and closed (cost to company, free to customer)
    o0 = completed_orders[0]
    u0 = unit_of(o0, "inverter")
    with at(20, 10):
        t = support.open_ticket(db, TicketIn(serial=u0.serial_no, channel="phone",
                                             issue="Inverter shows grid fault (E-03) since the rain, no generation."), sup)
        support.update_ticket(db, t.id, TicketUpdate(assigned_to=techs[0].id), sup)
    with at(19, 11):
        support.update_ticket(db, t.id, TicketUpdate(status="in_progress"), techs[0])
        spare = db.execute(select(StockUnit).where(StockUnit.product_id == u0.product_id,
                                                   StockUnit.status == "in_stock")).scalars().first()
        support.add_line(db, t.id, TicketLineIn(product_id=u0.product_id, replacement_serial=spare.serial_no, qty=1), techs[0])
        support.add_line(db, t.id, TicketLineIn(is_labour=True, description="Diagnosis and replacement", qty=2), techs[0])
        field.add_photo(db, "ticket", t.id, "after_repair", make_photo("inverter_serial"), "image/jpeg", lat, lng, fake_now())
        support.resolve_ticket(db, t.id, techs[0])
    with at(18, 12):
        support.close_ticket(db, t.id, True, sup)

    # 2) Out-of-warranty (legacy unit) -> billable, invoice created
    with at(9, 10):
        t2 = support.open_ticket(db, TicketIn(serial="GRW3K-2024LEG0007", channel="walk_in",
                                              issue="Inverter display blank, fan noise. Out of warranty."), sup)
        support.update_ticket(db, t2.id, TicketUpdate(assigned_to=techs[2].id), sup)
    with at(8, 12):
        support.update_ticket(db, t2.id, TicketUpdate(status="in_progress"), techs[2])
        support.add_line(db, t2.id, TicketLineIn(product_id=prods["DCDB-2S"].id, qty=1,
                                                 description="DCDB fuse and SPD replacement"), techs[2])
        support.add_line(db, t2.id, TicketLineIn(is_labour=True, qty=1.5, description="Repair labour"), techs[2])
        field.add_photo(db, "ticket", t2.id, "after_repair", make_photo("wiring"), "image/jpeg", 26.86, 75.82, fake_now())
        support.resolve_ticket(db, t2.id, techs[2])

    # 3) Overdue in-warranty ticket (opened 18 days ago, still in progress)
    u1 = unit_of(completed_orders[1], "inverter")
    with at(18, 15):
        t3 = support.open_ticket(db, TicketIn(serial=u1.serial_no, channel="phone",
                                              issue="Generation dropped by 40% for the last two weeks."), sup)
        support.update_ticket(db, t3.id, TicketUpdate(assigned_to=techs[1].id), sup)
    with at(16, 11):
        support.update_ticket(db, t3.id, TicketUpdate(status="in_progress"), techs[1])

    # 4) Fresh QR-raised ticket, unassigned
    u2 = unit_of(completed_orders[2], "inverter")
    with at(0.2, 9):
        support.open_ticket(db, TicketIn(serial=u2.serial_no, channel="qr",
                                         issue="Red light blinking on inverter after power cut last night."), None)

    # 5) Assigned, not started (panel cleaning complaint)
    u3 = unit_of(completed_orders[4], "panel")
    with at(3, 14):
        t5 = support.open_ticket(db, TicketIn(serial=u3.serial_no, channel="phone",
                                              issue="Bird droppings and a cracked panel corner noticed on one module."), sup)
        support.update_ticket(db, t5.id, TicketUpdate(assigned_to=techs[3].id), sup)

    # ----- overdue invoice: push one partially paid invoice past its due date -----
    inv = db.execute(select(Invoice).where(Invoice.order_id == completed_orders[7].id)).scalar_one()
    inv.due_date = (REAL_NOW - timedelta(days=12)).date()
    db.commit()

    # ----- technician pay: previous month already paid for two technicians -----
    first_of_month = REAL_NOW.date().replace(day=1)
    prev_month = (first_of_month - timedelta(days=1)).strftime("%Y-%m")
    for row in finance.pay_summary(db, prev_month):
        if row["hours"] > 0 and row["technician"]["id"] != techs[-1].id:  # leave one unpaid
            finance.create_pay_run(db, row["technician"]["id"], prev_month, acc)

    # A demo share link valid for 30 days
    with at(0, 9):
        reports.create_share(db, "October snapshot for our CA", first_of_month - timedelta(days=60), REAL_NOW.date(), 30, admin)

    counts = {m.__name__: db.query(m).count() for m in (User, Customer, Lead, Product, StockUnit, Job, Ticket, Invoice,
                                                        SubsidyCase)}
    db.close()
    return counts


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--reset", action="store_true", help="drop and recreate all tables first")
    args = parser.parse_args()
    if args.reset:
        reset()
    else:
        with engine.connect() as conn:
            if conn.execute(text("SELECT to_regclass('public.users')")).scalar():
                with SessionLocal() as s:
                    if s.query(User).count():
                        print("Database already has data. Use --reset to rebuild it.")
                        sys.exit(1)
        Base.metadata.create_all(engine)
    counts = run()
    print("Seeded:", ", ".join(f"{k}={v}" for k, v in counts.items()))
    print(f"All demo users share the password: {PASSWORD}")


if __name__ == "__main__":
    main()
